// Low-level output of words (16-bits)

unsigned short IO_PORT = 0x378; // LPT1 Data Port (Example)
unsigned long WORDS_TO_WRITE = 8;

// Data buffer (8 words = 16 bytes)
unsigned short data_words[8] = {0x00FF, 0x1234, 0x5678, 0x9ABC,
                                0xDE00, 0x1111, 0x2222, 0xFFFF};

// Write WORDS_TO_WRITE 16-bit words
// starting from data_words to IO_PORT
outsw(IO_PORT, data_words, WORDS_TO_WRITE);

